 const [members,setMembers]=useState<any[]>([]),[currentUser,setCurrentUser]=useState<any>(null),[nextActions,setNextActions]=useState<any[]>([]),[viewings,setViewings]=useState<any[]>([]),[viewingOpen,setViewingOpen]=useState(false);
