 useEffect(()=>{fetch("/api/settings").then(r=>r.ok?r.json():Promise.reject()).then(d=>{const a=d.agency||{},p=d.platform||{};setBrand(x=>({...x,platformName:p.platform_name||p.platformName||x.platformName,parentBrand:p.parent_brand||p.parentBrand||x.parentBrand,tenantDomainSuffix:p.tenant_domain_suffix||p.tenantDomainSuffix||x.tenantDomainSuffix,platformLogoUrl:p.logo_url||p.logoUrl||x.platformLogoUrl,platformIconUrl:p.icon_url||p.iconUrl||x.platformIconUrl,name:a.name||x.name,tagline:a.tagline??x.tagline,primaryColor:a.primary_color||a.primaryColor||x.primaryColor,accentColor:a.accent_color||a.accentColor||x.accentColor,phone:a.phone||"",whatsapp:a.whatsapp||"",email:a.email||"",website:a.website||"",slug:a.slug||"",websiteTemplate:a.website_template||a.websiteTemplate||"classic",typography:a.typography||"classic",businessActivities:Array.isArray(a.businessActivities)?a.businessActivities:JSON.parse(a.business_activities||"[]"),publicContent:Array.isArray(a.publicContent)?{}:typeof a.publicContent==="object"&&a.publicContent?a.publicContent:JSON.parse(a.public_content||"{}"),onboardingComplete:Boolean(a.onboarding_complete??a.onboardingComplete),responseSlaMinutes:Number(a.response_sla_minutes||a.responseSlaMinutes||30),logoId:a.logo_id||a.logoId||""}))}).catch(()=>{})},[]);
