 const activate=async(p:Property)=>{if(typeof p.id==="string"){const r=await fetch("/api/workspace/actions",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action:"activate_property",resourceId:p.id})});if(!r.ok){notify("Property needs more detail before activation.");return}}const next={...p,status:"Available" as const};setProperties(x=>x.map(row=>row.id===p.id?next:row));setSelected(next);notify("Property activated across website and marketing.")};
