 const completeAction=async(id:string)=>{const r=await fetch("/api/actions",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({id,operation:"complete"})});if(r.ok){notify("Action completed.");loadOps()}else notify("Action could not be completed.")};
